<?php
/**
 * Tests for the Excel readers (.xlsx and .xls) and the table conversion.
 *
 * Fixtures are generated by openpyxl (.xlsx) and xlwt (.xls, BIFF8).
 *
 * @package RekryteringsportalenXlsImport
 */

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class SpreadsheetTest extends TestCase {

	/**
	 * Both formats.
	 *
	 * @return array<string, array{0:string}>
	 */
	public static function files(): array {
		return array(
			'xlsx' => array( 'test.xlsx' ),
			'xls'  => array( 'test.xls' ),
		);
	}

	private function read( string $file, string $sheet = '' ): array {
		$path = __DIR__ . '/fixtures/' . $file;
		return RP_Spreadsheet::read( $path, pathinfo( $path, PATHINFO_EXTENSION ), $sheet );
	}

	#[DataProvider( 'files' )]
	public function test_picks_first_sheet_with_data_and_skips_empty_top_row( string $file ): void {
		$t = $this->read( $file );
		$this->assertSame( array( 'Info', 'Företag', 'Stor' ), $t['sheets'] );
		$this->assertSame( 'flik "Företag" (2 av 3)', $t['info'] );
		$this->assertSame( 'Företagsnamn', $t['headers'][0] );
	}

	#[DataProvider( 'files' )]
	public function test_headers_drop_empty_columns_and_dedupe( string $file ): void {
		$t = $this->read( $file );
		$this->assertSame(
			array( 'Företagsnamn', 'Org.nr', 'Hemsida', 'Län', 'Grundat', 'Paket giltigt till', 'Betyg', 'Aktiv', 'Formel', 'Org.nr (2)' ),
			$t['headers']
		);
	}

	#[DataProvider( 'files' )]
	public function test_values( string $file ): void {
		$rows = $this->read( $file )['rows'];
		$this->assertCount( 4, $rows, 'Blank rows are skipped.' );

		$this->assertSame( 'Ångström Bemanning AB', $rows[0]['Företagsnamn'] );
		$this->assertSame( '5566778899', $rows[0]['Org.nr'], 'Large integers keep all digits, no ".0" or exponent.' );
		$this->assertSame( '2010', $rows[0]['Grundat'] );
		$this->assertSame( '2027-01-31', $rows[0]['Paket giltigt till'], 'Date cells become ISO dates.' );
		$this->assertSame( '4.25', $rows[0]['Betyg'] );
		$this->assertSame( 'JA', $rows[0]['Aktiv'] );

		$this->assertSame( '556677-0001', $rows[1]['Org.nr'], 'Text stays text.' );
		$this->assertSame( '2026-12-31', $rows[1]['Paket giltigt till'], 'Other date formats (d/m/yyyy) are detected too.' );
		$this->assertSame( 'Östergötlands län', $rows[1]['Län'] );

		$this->assertSame( 'Ünïcødé – 東京 Talent', $rows[2]['Företagsnamn'], 'Non-Latin text is decoded.' );
		$this->assertSame( '-12', $rows[2]['Org.nr'] );
		$this->assertSame( '0.1', $rows[2]['Betyg'] );
		$this->assertSame( '', $rows[2]['Län'] );

		$this->assertSame( 'Sista Bolaget AB', $rows[3]['Företagsnamn'] );
	}

	#[DataProvider( 'files' )]
	public function test_large_sheet( string $file ): void {
		// 1 500 unique strings mixing Latin-1 and CJK: in .xls this spans several CONTINUE records
		// with switches between compressed and wide character encoding.
		$rows = $this->read( $file, 'Stor' )['rows'];
		$this->assertCount( 1500, $rows );
		foreach ( $rows as $i => $row ) {
			$expected = $i % 3 ? sprintf( 'Bolag nummer %04d åäö', $i ) : sprintf( '国際 Talent %04d 東京', $i );
			$this->assertSame( $expected, $row['namn'], "Row $i" );
			$this->assertSame( (string) ( 5590000000 + $i ), $row['orgnr'], "Row $i" );
		}
	}

	#[DataProvider( 'files' )]
	public function test_sheet_by_number_and_unknown_sheet( string $file ): void {
		$this->assertSame( 'flik "Stor" (3 av 3)', $this->read( $file, '3' )['info'] );
		$this->assertSame( 'flik "Stor" (3 av 3)', $this->read( $file, 'stor' )['info'], 'Case-insensitive name.' );
		$this->expectException( RuntimeException::class );
		$this->expectExceptionMessage( 'Flikar i filen: Info, Företag, Stor' );
		$this->read( $file, 'Saknas' );
	}

	public function test_template_matches_import_columns(): void {
		$path = dirname( __DIR__ ) . '/data/import-mall.xlsx';
		$t    = RP_Spreadsheet::read( $path, 'xlsx' );
		$this->assertSame( 'namn', $t['headers'][0] );
		$this->assertContains( 'paket_giltigt_till', $t['headers'] );
		$this->assertSame( '559999-0002', $t['rows'][1]['orgnr'] );
		$this->assertSame( '2027-12-31', $t['rows'][1]['paket_giltigt_till'] );
	}

	public function test_rejects_non_excel_files(): void {
		$tmp = tempnam( sys_get_temp_dir(), 'rp' );
		file_put_contents( $tmp, "namn;orgnr\nA;1\n" );
		try {
			$this->expectException( RuntimeException::class );
			RP_Spreadsheet::read( $tmp, 'xlsx' );
		} finally {
			unlink( $tmp );
		}
	}

	public function test_html_disguised_as_xls(): void {
		$tmp = tempnam( sys_get_temp_dir(), 'rp' );
		file_put_contents( $tmp, '<html><body><table><tr><td>namn</td></tr></table></body></html>' );
		try {
			$this->expectExceptionMessage( 'HTML-tabell' );
			RP_Spreadsheet::read( $tmp, 'xls' );
		} finally {
			unlink( $tmp );
		}
	}

	public function test_helpers(): void {
		$this->assertSame( 0, RP_Spreadsheet::column_index( 'A1' ) );
		$this->assertSame( 27, RP_Spreadsheet::column_index( 'AB12' ) );
		$this->assertSame( 'AB', RP_Spreadsheet::column_letter( 27 ) );
		$this->assertSame( '2026-12-31', RP_Spreadsheet::serial_to_date( 46387 ) );
		$this->assertSame( '2026-12-31', RP_Spreadsheet::serial_to_date( 44925, true ), '1904 date system' );
		$this->assertSame( '2026-12-31 12:00', RP_Spreadsheet::serial_to_date( 46387.5 ) );
		$this->assertSame( '1234567890123', RP_Spreadsheet::format_number( 1234567890123.0 ) );
		$this->assertSame( '3.5', RP_Spreadsheet::format_number( 3.5 ) );

		$this->assertTrue( RP_Spreadsheet::is_date_format( 14 ) );
		$this->assertTrue( RP_Spreadsheet::is_date_format( 164, 'yyyy-mm-dd' ) );
		$this->assertTrue( RP_Spreadsheet::is_date_format( 165, '[$-41D]d mmmm yyyy;@' ) );
		$this->assertFalse( RP_Spreadsheet::is_date_format( 2 ) );
		$this->assertFalse( RP_Spreadsheet::is_date_format( 166, '#,##0 "kr"' ) );
		$this->assertFalse( RP_Spreadsheet::is_date_format( 167, '0.00%' ) );
		$this->assertFalse( RP_Spreadsheet::is_date_format( 168, '[Red]#,##0' ) );
	}
}
